//! Interface constructors called without `new` (turbo-surf#86) throw Blink's
//! `Failed to construct 'X': Please use the 'new' operator, this DOM object constructor
//! cannot be called as a function.` (or `Illegal constructor` for interfaces without a
//! constructor) instead of V8's generic `Constructor requires 'new'`, for every
//! interface turbo-surf's bootstrap creates through the native factory (the interfaces
//! turbo-dom's own bootstrap creates, e.g. Node or CustomEvent, are not covered here);
//! `Date()` still returns a string and `new` keeps working. Expected values: Chrome 156 (156.0.8078.47, headless) running
//! the same script on a localhost page.
use serde_json::Value;
use turbo_surf_render::PageSession;

const SCRIPT: &str = r##"const out={};const names=["Date","DOMParser","Navigator","Performance","Permissions","PermissionsPolicy","PermissionStatus","Storage","Headers","Request","Response","URL","URLSearchParams","DOMException","MessageEvent","ErrorEvent","Event","SecurityPolicyViolationEvent","MessageChannel","MessagePort","BroadcastChannel","Blob","File","FormData","XMLHttpRequest","AbortController","AbortSignal","TextEncoder","TextDecoder","Screen","Window","Crypto","SubtleCrypto","IntersectionObserver","ResizeObserver","PerformanceObserver","PerformanceEntry","PerformanceMark","PerformanceMeasure","PerformanceNavigationTiming","EventCounts","DOMPointReadOnly","DOMPoint","DOMMatrixReadOnly","DOMMatrix","DOMQuad","WebKitCSSMatrix","StorageEvent","DOMRect","DOMRectReadOnly","ReadableStream","ReadableStreamDefaultReader","ReadableStreamBYOBReader","ReadableStreamDefaultController","ReadableByteStreamController","ReadableStreamBYOBRequest","WritableStream","WritableStreamDefaultWriter","WritableStreamDefaultController","TransformStream","TransformStreamDefaultController","ByteLengthQueuingStrategy","CountQueuingStrategy","XMLHttpRequestEventTarget","XMLHttpRequestUpload","FileReader","WebSocket","DOMStringList","History","ScreenOrientation","VisualViewport","PerformanceObserverEntryList","IntersectionObserverEntry","ResizeObserverEntry","DOMRectList","ResizeObserverSize","UserActivation","CryptoKey","CaretPosition"];
for(const n of names){const C=self[n];if(typeof C!=='function'){out[n]='missing';continue}
try{const r=C();out[n]='returned '+typeof r}catch(e){out[n]=e.name+': '+e.message}}
class Sub extends DOMPoint{};try{Sub()}catch(e){out.subclass=e.name+': '+e.message}
try{DOMPoint.call(new DOMPoint())}catch(e){out.callReceiver=e.name+': '+e.message}
try{Reflect.apply(Headers,null,[])}catch(e){out.reflectApply=e.name+': '+e.message}
out.newStillWorks=[new DOMPoint(1).x,new Headers({a:'b'}).get('a'),new URL('https://a.test/x').pathname,new DOMMatrix().is2D];
globalThis.out=out;"##;

const CHROME_156: &str = r##"{"Date":"returned string","DOMParser":"TypeError: Failed to construct 'DOMParser': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","Navigator":"TypeError: Illegal constructor","Performance":"TypeError: Illegal constructor","Permissions":"TypeError: Illegal constructor","PermissionsPolicy":"TypeError: Illegal constructor","PermissionStatus":"TypeError: Illegal constructor","Storage":"TypeError: Illegal constructor","Headers":"TypeError: Failed to construct 'Headers': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","Request":"TypeError: Failed to construct 'Request': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","Response":"TypeError: Failed to construct 'Response': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","URL":"TypeError: Failed to construct 'URL': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","URLSearchParams":"TypeError: Failed to construct 'URLSearchParams': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMException":"TypeError: Failed to construct 'DOMException': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","MessageEvent":"TypeError: Failed to construct 'MessageEvent': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","ErrorEvent":"TypeError: Failed to construct 'ErrorEvent': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","Event":"TypeError: Failed to construct 'Event': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","SecurityPolicyViolationEvent":"TypeError: Failed to construct 'SecurityPolicyViolationEvent': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","MessageChannel":"TypeError: Failed to construct 'MessageChannel': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","MessagePort":"TypeError: Illegal constructor","BroadcastChannel":"TypeError: Failed to construct 'BroadcastChannel': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","Blob":"TypeError: Failed to construct 'Blob': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","File":"TypeError: Failed to construct 'File': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","FormData":"TypeError: Failed to construct 'FormData': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","XMLHttpRequest":"TypeError: Failed to construct 'XMLHttpRequest': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","AbortController":"TypeError: Failed to construct 'AbortController': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","AbortSignal":"TypeError: Illegal constructor","TextEncoder":"TypeError: Failed to construct 'TextEncoder': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","TextDecoder":"TypeError: Failed to construct 'TextDecoder': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","Screen":"TypeError: Illegal constructor","Window":"TypeError: Illegal constructor","Crypto":"TypeError: Illegal constructor","SubtleCrypto":"TypeError: Illegal constructor","IntersectionObserver":"TypeError: Failed to construct 'IntersectionObserver': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","ResizeObserver":"TypeError: Failed to construct 'ResizeObserver': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","PerformanceObserver":"TypeError: Failed to construct 'PerformanceObserver': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","PerformanceEntry":"TypeError: Illegal constructor","PerformanceMark":"TypeError: Failed to construct 'PerformanceMark': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","PerformanceMeasure":"TypeError: Illegal constructor","PerformanceNavigationTiming":"TypeError: Illegal constructor","EventCounts":"TypeError: Illegal constructor","DOMPointReadOnly":"TypeError: Failed to construct 'DOMPointReadOnly': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMPoint":"TypeError: Failed to construct 'DOMPoint': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMMatrixReadOnly":"TypeError: Failed to construct 'DOMMatrixReadOnly': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMMatrix":"TypeError: Failed to construct 'DOMMatrix': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMQuad":"TypeError: Failed to construct 'DOMQuad': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","WebKitCSSMatrix":"TypeError: Failed to construct 'DOMMatrix': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","StorageEvent":"TypeError: Failed to construct 'StorageEvent': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMRect":"TypeError: Failed to construct 'DOMRect': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMRectReadOnly":"TypeError: Failed to construct 'DOMRectReadOnly': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","ReadableStream":"TypeError: Failed to construct 'ReadableStream': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","ReadableStreamDefaultReader":"TypeError: Failed to construct 'ReadableStreamDefaultReader': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","ReadableStreamBYOBReader":"TypeError: Failed to construct 'ReadableStreamBYOBReader': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","ReadableStreamDefaultController":"TypeError: Illegal constructor","ReadableByteStreamController":"TypeError: Illegal constructor","ReadableStreamBYOBRequest":"TypeError: Illegal constructor","WritableStream":"TypeError: Failed to construct 'WritableStream': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","WritableStreamDefaultWriter":"TypeError: Failed to construct 'WritableStreamDefaultWriter': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","WritableStreamDefaultController":"TypeError: Illegal constructor","TransformStream":"TypeError: Failed to construct 'TransformStream': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","TransformStreamDefaultController":"TypeError: Illegal constructor","ByteLengthQueuingStrategy":"TypeError: Failed to construct 'ByteLengthQueuingStrategy': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","CountQueuingStrategy":"TypeError: Failed to construct 'CountQueuingStrategy': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","XMLHttpRequestEventTarget":"TypeError: Illegal constructor","XMLHttpRequestUpload":"TypeError: Illegal constructor","FileReader":"TypeError: Failed to construct 'FileReader': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","WebSocket":"TypeError: Failed to construct 'WebSocket': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","DOMStringList":"TypeError: Illegal constructor","History":"TypeError: Illegal constructor","ScreenOrientation":"TypeError: Illegal constructor","VisualViewport":"TypeError: Illegal constructor","PerformanceObserverEntryList":"TypeError: Illegal constructor","IntersectionObserverEntry":"TypeError: Illegal constructor","ResizeObserverEntry":"TypeError: Illegal constructor","DOMRectList":"TypeError: Illegal constructor","ResizeObserverSize":"TypeError: Illegal constructor","UserActivation":"TypeError: Illegal constructor","CryptoKey":"TypeError: Illegal constructor","CaretPosition":"TypeError: Illegal constructor","subclass":"TypeError: Class constructor Sub cannot be invoked without 'new'","callReceiver":"TypeError: Failed to construct 'DOMPoint': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","reflectApply":"TypeError: Failed to construct 'Headers': Please use the 'new' operator, this DOM object constructor cannot be called as a function.","newStillWorks":[1,"b","/x",true]}"##;

#[tokio::test(flavor = "current_thread")]
async fn constructors_called_without_new_throw_blink_messages_like_chrome156() {
    let html = format!("<!doctype html><body><script>{SCRIPT}</script></body>");
    let mut page = PageSession::open(&html, "https://ctor.test/", "", "", 5000)
        .await
        .unwrap();
    let got: Value =
        serde_json::from_str(&page.eval_json_expression("out").await.unwrap()).unwrap();
    let chrome: Value = serde_json::from_str(CHROME_156).unwrap();
    let mut mismatched = Vec::new();
    for (key, want) in chrome.as_object().unwrap() {
        if got.get(key) != Some(want) {
            mismatched.push(format!("{key}: got {:?}, Chrome {want}", got.get(key)));
        }
    }
    assert!(mismatched.is_empty(), "{}", mismatched.join("\n"));
    assert_eq!(got, chrome);
}
